let db=loadDb(),session=JSON.parse(localStorage.getItem('manosuy_session')||'null'),page='home',authMode='login',filters={q:'',zone:'Todas',rating:'0',available:'all'};
db.assessments=db.assessments||[];
function loadDb(){const saved=JSON.parse(localStorage.getItem('manosuy_db')||'null');if(!saved||saved.version!==3)return structuredClone(seed);return saved}
function save(){localStorage.setItem('manosuy_db',JSON.stringify(db));localStorage.setItem('manosuy_session',JSON.stringify(session))}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function me(){return db.users.find(x=>x.id===session?.userId)}function user(id){return db.users.find(x=>x.id===id)}function workers(){return db.users.filter(x=>x.role==='worker')}function money(n=0){return '$ '+Number(n).toLocaleString('es-UY')}
function initials(n=''){return n.split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase()}
function serviceIcon(s){return SERVICES.find(x=>x[1]===s)?.[0]||'🧰'}
function photoData(photo){return typeof photo==='string'?'':photo?.data||''}
function photoName(photo){return typeof photo==='string'?photo:photo?.name||'Foto'}
function photoGallery(photos=[],label='Fotos del trabajo'){const valid=photos.filter(photoData);if(!valid.length)return '';return `<div class="photo-block"><div class="photo-label">📷 ${label} · ${valid.length}</div><div class="photo-gallery">${valid.map(p=>`<button class="photo-thumb" onclick="openPhoto('${encodeURIComponent(photoData(p))}','${esc(photoName(p))}')" aria-label="Ampliar ${esc(photoName(p))}"><img src="${photoData(p)}" alt="${esc(photoName(p))}" loading="lazy"><span>Ampliar</span></button>`).join('')}</div></div>`}
function openPhoto(encoded,name){openModal(esc(name),`<img class="photo-full" src="${decodeURIComponent(encoded)}" alt="${esc(name)}"><p class="muted">Imagen adjunta como evidencia dentro de ManosUY.</p>`)}
function fileToPhoto(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const img=new Image();img.onerror=reject;img.onload=()=>{const max=1280,scale=Math.min(1,max/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve({name:file.name,type:'image/jpeg',data:canvas.toDataURL('image/jpeg',.76)})};img.src=reader.result};reader.readAsDataURL(file)})}
async function filesToPhotos(files){return Promise.all([...files].slice(0,5).map(fileToPhoto))}
function app(){document.getElementById('app').innerHTML=session&&me()?layout():authView();document.getElementById('modal-root').innerHTML=''}
function authView(){return `<div class="auth"><section class="auth-panel"><div class="brand"><div class="brandmark"><span>✦</span></div>ManosUY</div><div class="eyebrow">Servicios de confianza</div><h1>${authMode==='login'?'Volvé a tener todo en buenas manos.':'Creá tu cuenta y empezá hoy.'}</h1><p class="sub">Profesionales verificados, presupuestos claros y seguimiento de principio a fin.</p><div class="tabs"><button class="${authMode==='login'?'active':''}" onclick="setAuth('login')">Ingresar</button><button class="${authMode==='register'?'active':''}" onclick="setAuth('register')">Crear cuenta</button></div>${authMode==='login'?loginForm():registerForm()}<div class="demo-box"><b>Accesos de prueba</b><br>Cliente: maria@demo.uy / 1234<br>Trabajador: carlos@demo.uy / 1234<br>Administrador: admin@manosuy.uy / admin123</div></section><section class="auth-visual"><div class="auth-visual-content"><div class="eyebrow" style="color:var(--lime)">Una red que resuelve</div><h2>Soluciones cerca.<br>Confianza siempre.</h2><p>Buscá, compará y contratá personas verificadas para cuidar tu casa, terreno o negocio.</p><div class="proof"><span>✓ Perfiles verificados</span><span>★ Reputación real</span><span>♻ Economía circular</span></div></div></section></div>`}
function loginForm(){return `<form onsubmit="login(event)"><label class="field">Correo electrónico</label><input class="input" name="email" type="email" required placeholder="tu@email.com"><label class="field" style="margin-top:13px">Contraseña</label><input class="input" name="password" type="password" required placeholder="••••••••"><button class="btn primary full" style="margin-top:18px">Ingresar a ManosUY</button></form>`}
function checks(selected=[]){return `<div class="service-checks">${SERVICES.map(([i,s])=>`<label class="check"><input type="checkbox" name="services" value="${s}" ${selected.includes(s)?'checked':''}><span>${i} ${s}</span></label>`).join('')}</div>`}
function registerForm(){return `<form onsubmit="register(event)"><div class="formgrid"><div><label class="field">Nombre completo</label><input class="input" name="name" required></div><div><label class="field">Teléfono</label><input class="input" name="phone" required></div><div><label class="field">Correo</label><input class="input" name="email" type="email" required></div><div><label class="field">Departamento</label><select class="input" name="zone">${ZONES.map(z=>`<option>${z}</option>`).join('')}</select></div><div><label class="field">Tipo de cuenta</label><select class="input" name="role" onchange="toggleRegisterServices(this.value)"><option value="client">Necesito contratar</option><option value="worker">Quiero ofrecer servicios</option></select></div><div><label class="field">Contraseña</label><input class="input" name="password" minlength="4" type="password" required></div><div class="fullcol" id="reg-services" style="display:none"><label class="field">¿Qué servicios ofrecés?</label>${checks()}</div></div><button class="btn primary full" style="margin-top:18px">Crear mi cuenta</button></form>`}
function navItems(){const r=me().role;return r==='client'?[['home','⌂','Inicio'],['find','⌕','Buscar'],['requests','▣','Solicitudes'],['history','◷','Historial'],['profile','○','Perfil']]:r==='worker'?[['home','⌂','Resumen'],['jobs','▣','Trabajos'],['earnings','$','Ganancias'],['profile','○','Perfil']]:[['home','⌂','Dashboard'],['users','♙','Usuarios'],['workers','♟','Profesionales'],['requests','▣','Trabajos'],['finance','$','Finanzas'],['recycling','♻','Materiales'],['claims','!','Reclamos']]}
function nav(){return navItems().map(([p,i,t])=>`<button class="navbtn ${page===p?'active':''}" onclick="go('${p}')"><span class="navico">${i}</span>${t}</button>`).join('')}
function layout(){const u=me();return `<div class="shell"><header class="topbar"><div class="brand"><div class="brandmark"><span>✦</span></div>ManosUY</div><div class="top-actions"><button class="btn small" onclick="openHelp()">¿Cómo funciona?</button><div class="user-pill"><div class="mini-avatar">${initials(u.name)}</div><div><b>${esc(u.name)}</b><small>${roleLabel(u.role)}</small></div></div><button class="btn ghost small" onclick="logout()">Salir</button></div></header><div class="layout"><aside class="sidebar"><div class="navlabel">MENÚ PRINCIPAL</div><nav>${nav()}</nav><div class="side-trust"><b>🛡 Confianza ManosUY</b><p>Identidad, documentos y reputación para contratar con tranquilidad.</p></div></aside><main class="main">${render()}</main></div><nav class="mobile-nav">${navItems().slice(0,5).map(([p,i,t])=>`<button class="navbtn ${page===p?'active':''}" onclick="go('${p}')"><span class="navico">${i}</span>${t}</button>`).join('')}</nav></div>`}
function render(){const r=me().role;if(r==='client')return page==='home'?clientHome():page==='find'?findView():page==='profile'?profileView():requestsView(page==='history');if(r==='worker')return page==='home'?workerHome():page==='jobs'?workerJobs():page==='earnings'?earnings():profileView();return page==='home'?adminHome():adminPage()}
function clientHome(){const mine=db.requests.filter(r=>r.clientId===me().id),active=mine.filter(r=>!['completed','rejected'].includes(r.status));return `<section class="hero-card"><div class="hero-copy"><div class="eyebrow">Tu próximo trabajo empieza acá</div><h1>¿Qué necesitás resolver?</h1><p>Encontrá profesionales verificados cerca tuyo y recibí un presupuesto sin vueltas.</p><form class="quick-search" onsubmit="homeSearch(event)"><input name="q" placeholder="Ej: plomero, cortar pasto, retirar escombros…"><button class="btn lime">Buscar profesionales</button></form></div></section><div class="grid four mt">${stat('🟢','Disponibles ahora',workers().filter(w=>w.verified&&w.available&&w.active).length,'En tu red ManosUY')}${stat('▣','Trabajos activos',active.length,'Con seguimiento')}${stat('★','Valoración media','4,8','Opiniones verificadas')}${stat('♻','Material recuperado','3,2 m³','Economía circular')}</div><section class="card mt"><div class="sectionhead"><h2>Servicios más buscados</h2><button class="linkbtn" onclick="go('find')">Ver todos →</button></div><div class="grid categories">${SERVICES.slice(0,8).map(([i,s])=>`<button class="category" onclick="pickService('${s}')"><div class="cat-icon">${i}</div><b>${s}</b><small>Ver profesionales</small></button>`).join('')}</div></section><div class="grid two mt"><section class="card"><div class="sectionhead"><h2>Tu actividad</h2><button class="linkbtn" onclick="go('requests')">Ver solicitudes</button></div>${mine.slice(-3).reverse().map(activityItem).join('')||empty('Todavía no hiciste solicitudes','Tu primer profesional está a pocos clics.')}</section><section class="card"><div class="sectionhead"><h2>♻ Retiro con beneficio</h2><span class="badge green">Economía circular</span></div><p class="muted">Entregá materiales recuperables y obtené un descuento estimado en el retiro. ManosUY se ocupa de clasificarlos.</p><div class="progress" style="margin:22px 0 8px"><span style="width:72%"></span></div><small class="muted">72% de los retiros registrados recuperaron materiales</small><button class="btn primary full" style="margin-top:19px" onclick="pickService('Retiro de escombros')">Solicitar un retiro</button></section></div>`}
function stat(icon,label,value,note){return `<div class="card"><div class="stat-icon">${icon}</div><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`}
function activityItem(r){return `<div class="list-item"><div class="list-icon">${serviceIcon(r.service)}</div><div class="grow"><b>${esc(r.service)}</b><div class="meta">#${r.id} · ${statusLabel(r.status)}</div></div><span class="badge ${statusClass(r.status)}">${statusLabel(r.status)}</span></div>`}
function findView(){let list=workers().filter(w=>w.verified&&w.active);const q=filters.q.toLowerCase().trim();if(q)list=list.filter(w=>w.name.toLowerCase().includes(q)||(w.services||[]).some(s=>s.toLowerCase().includes(q)));if(filters.zone!=='Todas')list=list.filter(w=>w.zone===filters.zone);if(+filters.rating)list=list.filter(w=>w.rating>=+filters.rating);if(filters.available==='yes')list=list.filter(w=>w.available);list.sort((a,b)=>(b.available-a.available)||(b.rating-a.rating));return `<div class="pagehead"><div><div class="eyebrow">Profesionales verificados</div><h1 class="h1">Encontrá la persona indicada</h1><p class="sub">Compará experiencia, reputación y disponibilidad.</p></div><button class="btn primary" onclick="openGeneralRequest()">+ Publicar una solicitud</button></div><div class="card flat"><div class="filters"><input class="input" value="${esc(filters.q)}" oninput="setFilter('q',this.value)" placeholder="⌕ Oficio o nombre"><select class="input" onchange="setFilter('zone',this.value)"><option>Todas</option>${ZONES.map(z=>`<option ${filters.zone===z?'selected':''}>${z}</option>`).join('')}</select><select class="input" onchange="setFilter('rating',this.value)"><option value="0">Cualquier valoración</option><option value="4.5" ${filters.rating==='4.5'?'selected':''}>4,5 estrellas o más</option><option value="4.8" ${filters.rating==='4.8'?'selected':''}>4,8 estrellas o más</option></select><select class="input" onchange="setFilter('available',this.value)"><option value="all">Toda disponibilidad</option><option value="yes" ${filters.available==='yes'?'selected':''}>Disponible ahora</option></select></div></div><p class="muted">${list.length} profesional${list.length!==1?'es':''} encontrado${list.length!==1?'s':''}</p><div class="grid">${list.map(workerCard).join('')||empty('No encontramos coincidencias','Probá con otros filtros o publicá una solicitud.')}</div>`}
function workerCard(w){return `<article class="card worker-card"><div class="avatar">${initials(w.name)}</div><div><div class="row" style="justify-content:flex-start"><h3>${esc(w.name)}</h3>${w.available?'<span class="badge green">● Disponible</span>':'<span class="badge">No disponible</span>'}</div><div><span class="stars">★ ${String(w.rating).replace('.',',')}</span> <span class="meta">(${w.jobs} trabajos) · ${w.zone}</span></div><div class="chips"><span class="chip verified">✓ Verificado</span><span class="chip">${levelIcon(w.level)} ${w.level}</span>${w.services.slice(0,3).map(s=>`<span class="chip">${esc(s)}</span>`).join('')}</div></div><button class="btn primary" onclick="openWorker('${w.id}')">Ver perfil</button></article>`}
function openWorker(id){const w=user(id),reviews=db.ratings.filter(r=>r.workerId===id);openModal(`${esc(w.name)} <span class="badge green">✓ Verificado</span>`,`<div class="worker-card" style="grid-template-columns:auto 1fr"><div class="avatar big">${initials(w.name)}</div><div><div class="stars">★ ${w.rating} · ${w.jobs} trabajos</div><div class="meta">${w.zone} · ${w.experience||0} años de experiencia</div></div></div><p>${esc(w.bio)}</p><h3>Servicios</h3><div class="chips">${w.services.map(s=>`<span class="chip">${serviceIcon(s)} ${s}</span>`).join('')}</div><h3 style="margin-top:22px">Opiniones</h3>${reviews.map(r=>`<div class="list-item"><div class="list-icon">★</div><div><b>${r.rating}/5</b><div class="muted">${esc(r.comment)}</div></div></div>`).join('')||'<p class="muted">Todavía no hay comentarios escritos.</p>'}<button class="btn primary full" onclick="openRequest('${id}')">Solicitar presupuesto</button>`) }
function openRequest(workerId='',preset=''){const w=workerId?user(workerId):null;openModal('Solicitar presupuesto',`<form onsubmit="createRequest(event,'${workerId}')"><div class="formgrid"><div><label class="field">Servicio</label><select class="input" name="service" required><option value="">Elegí una opción</option>${SERVICES.filter(x=>!w||w.services.includes(x[1])).map(x=>`<option ${preset===x[1]?'selected':''}>${x[1]}</option>`).join('')}</select></div><div><label class="field">Departamento</label><select class="input" name="zone">${ZONES.map(z=>`<option ${me().zone===z?'selected':''}>${z}</option>`).join('')}</select></div><div class="fullcol"><label class="field">Dirección o zona aproximada</label><input class="input" name="address" required placeholder="Ej: Barrio Centro"></div><div class="fullcol"><label class="field">Contanos qué necesitás</label><textarea class="input" name="description" rows="4" required placeholder="Incluí medidas, estado actual y toda información útil"></textarea></div><label class="check"><input type="checkbox" name="urgent"> 🚨 Es urgente</label><label class="check"><input type="checkbox" name="materials"> ♻ Entrego material recuperable</label><div class="fullcol"><label class="field">Fotos del trabajo (opcional)</label><input class="input" name="photos" type="file" accept="image/*" multiple></div></div><div class="notice" style="margin-top:15px">No se realiza ningún cobro ahora. ${w?'El profesional':'Los profesionales'} podrá${w?'':'n'} evaluar el trabajo y enviar un presupuesto.</div><button class="btn primary full" style="margin-top:18px">Enviar solicitud</button></form>`) }
function requestsView(history=false){let list=db.requests.filter(r=>r.clientId===me().id&&(['completed','rejected'].includes(r.status)===history)).sort((a,b)=>b.created-a.created);return `<div class="pagehead"><div><div class="eyebrow">${history?'Tu recorrido':'Seguimiento en tiempo real'}</div><h1 class="h1">${history?'Historial de trabajos':'Mis solicitudes'}</h1><p class="sub">${history?'Consultá trabajos anteriores, comprobantes y calificaciones.':'Presupuestos, trabajos activos y próximos pasos.'}</p></div>${history?'':'<button class="btn primary" onclick="openGeneralRequest()">+ Nueva solicitud</button>'}</div><div class="grid">${list.map(clientRequestCard).join('')||empty(history?'No hay trabajos anteriores':'No hay solicitudes activas',history?'Cuando completes un trabajo aparecerá acá.':'Publicá lo que necesitás y recibí un presupuesto.')}</div>`}
function clientRequestCard(r){const w=user(r.workerId),rated=db.ratings.some(x=>x.requestId===r.id),a=assessmentFor(r.id);return `<article class="card request-card lift-card"><div class="row"><div><span class="badge ${statusClass(r.status)}">${statusLabel(r.status)}</span><h3>${serviceIcon(r.service)} ${esc(r.service)}</h3><div class="meta">#${r.id} · ${esc(r.zone)} · ${new Date(r.created).toLocaleDateString('es-UY')}</div></div>${r.quote?`<div class="money">${money(r.quote-(r.discount||0))}</div>`:''}</div><p>${esc(r.description)}</p><div class="chips">${w?`<span class="chip">Profesional: ${esc(w.name)}</span>`:'<span class="chip">Solicitud abierta</span>'}${r.urgent?'<span class="chip">🚨 Urgente</span>':''}${r.materials?`<span class="chip">♻ ${assessmentLabel(a)}</span>`:''}</div>${photoGallery(r.photos,'Tus fotos del trabajo')}${a?photoGallery(a.evidence,'Evidencia del profesional'):''}${r.status==='quoted'?`<div class="quote-box"><div><b>Presupuesto recibido</b><div class="meta">${r.duration||'A coordinar'}${r.discount?` · Descuento aprobado: ${money(r.discount)}`:''}</div></div><div class="money">${money(r.quote-(r.discount||0))}</div></div>`:''}<div class="actions">${r.status==='quoted'?`<button class="btn primary" onclick="changeStatus('${r.id}','in_progress','Presupuesto aceptado')">Aceptar presupuesto</button><button class="btn" onclick="changeStatus('${r.id}','rejected','Presupuesto rechazado')">Rechazar</button>`:''}${r.status==='in_progress'?`<button class="btn primary" onclick="changeStatus('${r.id}','completed','Trabajo finalizado')">Confirmar finalización</button>`:''}${r.status==='completed'&&!rated?`<button class="btn primary" onclick="openRating('${r.id}')">★ Calificar</button>`:''}${w&&['quoted','in_progress'].includes(r.status)?`<button class="btn" onclick="openChat('${r.id}')">💬 Mensajes</button>`:''}${r.status==='completed'?`<button class="btn" onclick="openReceipt('${r.id}')">Ver comprobante</button><button class="btn ghost" onclick="openClaim('${r.id}')">Hacer reclamo</button>`:''}</div></article>`}
function workerHome(){const u=me(),rs=db.requests.filter(r=>r.workerId===u.id),active=rs.filter(r=>!['completed','rejected'].includes(r.status));return `<div class="pagehead"><div><div class="eyebrow">Panel profesional</div><h1 class="h1">Hola, ${esc(u.name.split(' ')[0])} 👋</h1><p class="sub">${u.verified?'Tu perfil está verificado y visible para clientes.':'Completá la verificación para aparecer en las búsquedas.'}</p></div><button class="btn ${u.available?'primary':''}" onclick="toggleAvailability()">${u.available?'● Disponible ahora':'○ Marcar disponible'}</button></div>${!u.verified?'<div class="notice">🛡 Tu documentación está pendiente de revisión. Podés agregar comprobantes desde Mi perfil.</div>':''}<div class="grid four mt">${stat('▣','Nuevas solicitudes',active.filter(r=>r.status==='pending').length,'Esperan respuesta')}${stat('★','Calificación',u.rating||'Nuevo',`${u.jobs} trabajos realizados`)}${stat(levelIcon(u.level),'Nivel actual',u.level,'Basado en desempeño')}${stat('$','Ganancia neta',money(netEarnings(u.id)),'Después de comisión')}</div><div class="grid two mt"><section class="card"><div class="sectionhead"><h2>Solicitudes por responder</h2><button class="linkbtn" onclick="go('jobs')">Ver todas →</button></div>${active.filter(r=>r.status==='pending').map(workerActivity).join('')||empty('Estás al día','No hay nuevas solicitudes por ahora.')}</section><section class="card"><h2>Tu reputación</h2><div class="row" style="margin:20px 0"><div><div class="stat-value">${u.rating||'—'} <span class="stars">★</span></div><div class="muted">Promedio de clientes</div></div><div style="text-align:right"><div class="stat-value">${u.jobs}</div><div class="muted">Trabajos terminados</div></div></div><div class="progress"><span style="width:${Math.min(100,(u.jobs/300)*100)}%"></span></div><p class="muted">${u.level==='Premium'?'Alcanzaste el nivel más alto.':`Seguí sumando trabajos y buenas opiniones para crecer de nivel.`}</p></section></div>`}
function workerActivity(r){const a=assessmentFor(r.id);return `<div class="list-item"><div class="list-icon">${serviceIcon(r.service)}</div><div class="grow"><b>${esc(r.service)}</b><div class="meta">${esc(user(r.clientId)?.name)} · ${r.zone}${r.urgent?' · Urgente':''}</div><div>${esc(r.description)}</div>${r.materials?`<div style="margin-top:7px"><span class="badge ${a?.status==='approved'?'green':a?'yellow':'blue'}">♻ ${assessmentLabel(a)}</span></div>`:''}</div>${r.materials&&a?.status!=='approved'?`<button class="btn small" onclick="openAssessment('${r.id}')">${a?'Editar informe':'Informar materiales'}</button>`:`<button class="btn small primary" onclick="openQuote('${r.id}')">Cotizar</button>`}</div>`}
function workerJobs(){const list=db.requests.filter(r=>r.workerId===me().id).sort((a,b)=>b.created-a.created);return `<div class="pagehead"><div><div class="eyebrow">Tu agenda</div><h1 class="h1">Trabajos y solicitudes</h1><p class="sub">Respondé, coordiná y cerrá cada trabajo.</p></div></div><div class="grid">${list.map(workerJobCard).join('')||empty('No tenés solicitudes','Cuando un cliente te elija, aparecerá acá.')}</div>`}
function workerJobCard(r){const a=assessmentFor(r.id),canQuote=!r.materials||a?.status==='approved';return `<article class="card request-card lift-card"><div class="row"><div><span class="badge ${statusClass(r.status)}">${statusLabel(r.status)}</span><h3>${serviceIcon(r.service)} ${esc(r.service)}</h3><div class="meta">${esc(user(r.clientId)?.name)} · ${r.zone} · #${r.id}</div></div>${r.quote?`<div class="money">${money(r.quote-r.discount)}</div>`:''}</div><p>${esc(r.description)}</p><div class="chips">${r.urgent?'<span class="chip">🚨 Urgente</span>':''}<span class="chip">📍 ${esc(r.address)}</span>${r.materials?`<span class="chip">♻ ${assessmentLabel(a)}</span>`:''}</div>${photoGallery(r.photos,'Fotos enviadas por el cliente')}${a?assessmentSummary(a):''}${a?photoGallery(a.evidence,'Tus fotos del material'):''}<div class="actions">${r.status==='pending'&&r.materials?`<button class="btn" onclick="openAssessment('${r.id}')">${a?'Actualizar informe':'Informar materiales'}</button>`:''}${r.status==='pending'&&canQuote?`<button class="btn primary" onclick="openQuote('${r.id}')">Enviar presupuesto final</button>`:''}${r.status==='pending'?`<button class="btn" onclick="changeStatus('${r.id}','rejected','Solicitud rechazada')">No puedo tomarlo</button>`:''}${r.status==='in_progress'?`<button class="btn primary" onclick="changeStatus('${r.id}','completed','Trabajo finalizado')">Marcar finalizado</button>`:''}${['quoted','in_progress'].includes(r.status)?`<button class="btn" onclick="openChat('${r.id}')">💬 Mensajes</button>`:''}</div></article>`}
function earnings(){const done=db.requests.filter(r=>r.workerId===me().id&&r.status==='completed'),gross=done.reduce((a,r)=>a+(r.quote||0),0),fee=Math.round(gross*.15);return `<div class="pagehead"><div><div class="eyebrow">Finanzas transparentes</div><h1 class="h1">Mis ganancias</h1><p class="sub">Comisión de plataforma: 15% sobre trabajos completados.</p></div><button class="btn" onclick="toast('Estado de cuenta descargado')">↓ Descargar estado</button></div><div class="grid three">${stat('$','Total facturado',money(gross),'Trabajos completados')}${stat('−','Comisión ManosUY',money(fee),'15% de servicio')}${stat('✓','Neto estimado',money(gross-fee),'Disponible')}</div><section class="card mt"><h2>Movimientos</h2>${done.map(r=>`<div class="list-item"><div class="list-icon">${serviceIcon(r.service)}</div><div class="grow"><b>${r.service}</b><div class="meta">#${r.id} · ${new Date(r.created).toLocaleDateString('es-UY')}</div></div><div style="text-align:right"><b>${money((r.quote||0)*.85)}</b><div class="meta">neto</div></div></div>`).join('')||empty('Sin movimientos','Tus trabajos completados aparecerán acá.')}</section>`}
function profileView(){const u=me();return `<div class="pagehead"><div><div class="eyebrow">Cuenta y seguridad</div><h1 class="h1">Mi perfil</h1><p class="sub">Mantené tu información actualizada.</p></div></div><div class="grid two"><section class="card"><div class="worker-card" style="grid-template-columns:auto 1fr"><div class="avatar big">${initials(u.name)}</div><div><h3>${esc(u.name)}</h3><div class="meta">${roleLabel(u.role)} · ${u.zone}</div>${u.role==='worker'?`<div class="stars">★ ${u.rating||'Nuevo'}</div>`:''}</div></div><form onsubmit="saveProfile(event)" style="margin-top:22px"><div class="formgrid"><div><label class="field">Nombre</label><input class="input" name="name" value="${esc(u.name)}" required></div><div><label class="field">Teléfono</label><input class="input" name="phone" value="${esc(u.phone||'')}" required></div><div><label class="field">Departamento</label><select class="input" name="zone">${ZONES.map(z=>`<option ${u.zone===z?'selected':''}>${z}</option>`).join('')}</select></div><div><label class="field">Correo</label><input class="input" value="${esc(u.email)}" disabled></div>${u.role==='worker'?`<div class="fullcol"><label class="field">Presentación profesional</label><textarea class="input" name="bio" rows="4">${esc(u.bio||'')}</textarea></div><div><label class="field">Años de experiencia</label><input class="input" name="experience" type="number" min="0" value="${u.experience||0}"></div><div><label class="field">Disponibilidad</label><select class="input" name="available"><option value="true" ${u.available?'selected':''}>Disponible</option><option value="false" ${!u.available?'selected':''}>No disponible</option></select></div><div class="fullcol"><label class="field">Servicios que ofrecés</label>${checks(u.services)}</div>`:''}</div><button class="btn primary" style="margin-top:18px">Guardar cambios</button></form></section><section class="card"><div class="sectionhead"><h2>Seguridad y verificación</h2>${u.role==='worker'?`<span class="badge ${u.verified?'green':'yellow'}">${u.verified?'✓ Verificado':'Pendiente'}</span>`:'<span class="badge green">✓ Cuenta activa</span>'}</div><div class="list-item"><div class="list-icon">✉</div><div><b>Correo de acceso</b><div class="muted">${esc(u.email)}</div></div></div>${u.role==='worker'?`<h2 style="margin-top:22px">Documentación profesional</h2>${(u.documents||[]).map(d=>`<div class="list-item"><div class="list-icon">▤</div><div class="grow"><b>${esc(d.name)}</b><div class="muted">${d.type}</div></div><span class="badge ${d.status==='approved'?'green':'yellow'}">${d.status==='approved'?'Aprobado':'En revisión'}</span></div>`).join('')}<form onsubmit="addDocument(event)"><label class="field" style="margin-top:15px">Agregar título, certificado o habilitación</label><select class="input" name="type"><option>Título</option><option>Certificado</option><option>Habilitación</option><option>Identidad</option></select><input class="input" name="document" type="file" required style="margin-top:9px"><button class="btn full" style="margin-top:9px">Subir documento</button></form>`:''}<button class="btn danger" style="margin-top:24px" onclick="logout()">Cerrar sesión</button></section></div>`}
function adminHome(){const completed=db.requests.filter(r=>r.status==='completed'),gross=completed.reduce((a,r)=>a+(r.quote||0),0);return `<div class="pagehead"><div><div class="eyebrow">Centro de operaciones</div><h1 class="h1">Todo ManosUY, en una vista</h1><p class="sub">Actividad, confianza, finanzas y economía circular.</p></div><button class="btn primary" onclick="toast('Reporte ejecutivo generado')">Generar reporte</button></div><div class="grid four">${stat('♙','Usuarios activos',db.users.filter(u=>u.role!=='admin'&&u.active).length,'Clientes y profesionales')}${stat('♟','Profesionales',workers().length,`${workers().filter(w=>!w.verified).length} por verificar`)}${stat('▣','Trabajos activos',db.requests.filter(r=>!['completed','rejected'].includes(r.status)).length,'Operación actual')}${stat('$','Comisiones',money(gross*.15),'Sobre trabajos cerrados')}</div><div class="grid two mt"><section class="card"><div class="sectionhead"><h2>Operaciones recientes</h2><button class="linkbtn" onclick="go('requests')">Ver todas →</button></div>${db.requests.slice().reverse().map(activityItem).join('')}</section><section class="card"><h2>Alertas que requieren atención</h2><div class="list-item"><div class="list-icon">🛡</div><div class="grow"><b>${workers().filter(w=>!w.verified).length} verificaciones pendientes</b><div class="muted">Revisar documentos profesionales</div></div><button class="btn small" onclick="go('workers')">Revisar</button></div><div class="list-item"><div class="list-icon">!</div><div class="grow"><b>${db.claims.filter(c=>c.status==='open').length} reclamos abiertos</b><div class="muted">Casos que esperan resolución</div></div><button class="btn small" onclick="go('claims')">Gestionar</button></div><div class="list-item"><div class="list-icon">♻</div><div class="grow"><b>${db.materials.length} lotes recuperados</b><div class="muted">Valor estimado ${money(db.materials.reduce((a,m)=>a+(m.value||0),0))}</div></div></div></section></div>`}
function adminPage(){if(page==='users')return adminUsers();if(page==='workers')return adminWorkers();if(page==='requests')return adminRequests();if(page==='finance')return adminFinance();if(page==='recycling')return adminRecycling();return adminClaims()}
function adminHead(k,t,s,a=''){return `<div class="pagehead"><div><div class="eyebrow">${k}</div><h1 class="h1">${t}</h1><p class="sub">${s}</p></div>${a}</div>`}
function table(headers,rows){return `<div class="card tablewrap"><table class="table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function adminUsers(){const list=db.users.filter(u=>u.role==='client');return adminHead('Comunidad','Clientes','Cuentas, actividad y estado.')+table(['Cliente','Contacto','Zona','Estado','Acción'],list.map(u=>[`<b>${esc(u.name)}</b>`,esc(u.email),u.zone,`<span class="badge ${u.active?'green':'red'}">${u.active?'Activo':'Suspendido'}</span>`,`<button class="btn small" onclick="toggleUser('${u.id}')">${u.active?'Suspender':'Reactivar'}</button>`]))}
function adminWorkers(){return adminHead('Confianza','Profesionales','Documentación, servicios y reputación.')+table(['Profesional','Servicios','Reputación','Documentos','Estado','Acción'],workers().map(w=>[`<b>${esc(w.name)}</b><div class="meta">${w.zone}</div>`,w.services.slice(0,2).join(', '),`★ ${w.rating||'Nuevo'} · ${w.jobs}`,`${(w.documents||[]).length} archivo(s)`,`<span class="badge ${w.verified?'green':'yellow'}">${w.verified?'Verificado':'Pendiente'}</span>`,`<button class="btn small ${w.verified?'':'primary'}" onclick="reviewWorker('${w.id}')">Revisar</button>`]))}
function adminRequests(){return adminHead('Operaciones','Todos los trabajos','Seguimiento completo de solicitudes, fotos y presupuestos.')+table(['ID','Servicio','Cliente','Profesional','Evidencia','Estado','Acción'],db.requests.map(r=>['#'+r.id,r.service,esc(user(r.clientId)?.name||''),esc(user(r.workerId)?.name||'Abierta'),`${(r.photos||[]).length} foto(s)`,`<span class="badge ${statusClass(r.status)}">${statusLabel(r.status)}</span>`,`<button class="btn small" onclick="openAdminRequest('${r.id}')">Ver trabajo</button>`]))}
function openAdminRequest(id){const r=db.requests.find(x=>x.id===id),a=assessmentFor(id);openModal(`Trabajo #${id} · ${esc(r.service)}`,`<div class="row"><div><span class="badge ${statusClass(r.status)}">${statusLabel(r.status)}</span><p class="meta">${esc(user(r.clientId)?.name||'')} · ${esc(user(r.workerId)?.name||'Sin profesional')} · ${esc(r.zone)}</p></div>${r.quote?`<div class="money">${money(r.quote-(r.discount||0))}</div>`:''}</div><p>${esc(r.description)}</p>${photoGallery(r.photos,'Fotos enviadas por el cliente')}${a?`<hr style="border:0;border-top:1px solid var(--line);margin:22px 0">${assessmentSummary(a)}${photoGallery(a.evidence,'Evidencia del trabajador')}`:''}`)}
function adminFinance(){const gross=db.requests.filter(r=>r.status==='completed').reduce((a,r)=>a+(r.quote||0),0);return adminHead('Finanzas','Movimientos','Volumen, comisiones y pagos.')+`<div class="grid three">${stat('$','Volumen operado',money(gross),'Trabajos completados')}${stat('+','Comisión ManosUY',money(gross*.15),'Ingresos de plataforma')}${stat('→','Pago a profesionales',money(gross*.85),'Neto acumulado')}</div>`+table(['Concepto','Base','Tasa','Total'],[['Comisión de plataforma',money(gross),'15%',money(gross*.15)],['Pagos profesionales',money(gross),'85%',money(gross*.85)]])}
function adminRecycling(){const pending=db.assessments.filter(a=>a.status==='pending');return adminHead('Economía circular','Evaluación de recuperables','La empresa define el descuento antes del presupuesto final.','<button class="btn primary" onclick="openMaterial()">+ Registrar lote</button>')+(pending.length?`<section class="card" style="margin-bottom:18px"><div class="sectionhead"><h2>Informes por revisar</h2><span class="badge yellow">${pending.length} pendiente${pending.length!==1?'s':''}</span></div>${pending.map(a=>`<div class="list-item"><div class="list-icon">♻</div><div class="grow"><b>${esc(a.material)} · ${esc(a.quantity)} ${esc(a.unit)}</b><div class="meta">Trabajo #${a.requestId} · ${esc(user(a.workerId)?.name)} · Calidad: ${esc(a.condition)}</div><div>${esc(a.notes||'Sin observaciones')}</div></div><button class="btn small primary" onclick="reviewAssessment('${a.id}')">Evaluar</button></div>`).join('')}</section>`:'')+table(['Material','Volumen','Trabajo origen','Estado','Valor'],db.materials.map(m=>[m.type,m.volume,'#'+m.requestId,`<span class="badge green">${m.status}</span>`,money(m.value)]))}
function adminClaims(){return adminHead('Soporte','Reclamos','Mediación y resolución de casos.')+(db.claims.length?table(['Caso','Trabajo','Motivo','Estado','Acción'],db.claims.map(c=>['#'+c.id,'#'+c.requestId,esc(c.reason),`<span class="badge ${c.status==='open'?'yellow':'green'}">${c.status==='open'?'Abierto':'Resuelto'}</span>`,`<button class="btn small" onclick="resolveClaim('${c.id}')">Resolver</button>`])):`<div class="card">${empty('No hay reclamos abiertos','La operación está al día.')}</div>`)}
function assessmentFor(requestId){return db.assessments.find(a=>a.requestId===requestId)}
function assessmentLabel(a){return !a?'Materiales sin informar':a.status==='approved'?`Descuento aprobado: ${money(a.discount)}`:a.status==='rejected'?'Revisión solicitada':'Evaluación pendiente de la empresa'}
function assessmentSummary(a){return `<div class="notice" style="margin-top:14px;background:${a.status==='approved'?'var(--mint)':'#fff7e8'};color:${a.status==='approved'?'var(--green)':'#775522'}"><b>♻ ${assessmentLabel(a)}</b><br>${esc(a.material)} · ${esc(a.quantity)} ${esc(a.unit)} · Estado: ${esc(a.condition)}${a.adminNote?`<br>Empresa: ${esc(a.adminNote)}`:''}</div>`}
function openAssessment(id){const r=db.requests.find(x=>x.id===id),a=assessmentFor(id);openModal(a?'Actualizar informe de materiales':'Informar materiales recuperables',`<p class="muted">Este informe será revisado por ManosUY antes de que puedas enviar el presupuesto final.</p><form onsubmit="submitAssessment(event,'${id}')"><div class="formgrid"><div><label class="field">Tipo de material</label><select class="input" name="material"><option ${a?.material==='Escombro limpio'?'selected':''}>Escombro limpio</option><option ${a?.material==='Pasto y restos verdes'?'selected':''}>Pasto y restos verdes</option><option ${a?.material==='Cañería metálica'?'selected':''}>Cañería metálica</option><option ${a?.material==='Cañería plástica'?'selected':''}>Cañería plástica</option><option ${a?.material==='Madera recuperable'?'selected':''}>Madera recuperable</option><option ${a?.material==='Metales'?'selected':''}>Metales</option><option ${a?.material==='Cartón y embalajes'?'selected':''}>Cartón y embalajes</option><option ${a?.material==='Otro material'?'selected':''}>Otro material</option></select></div><div><label class="field">Estado del material</label><select class="input" name="condition"><option ${a?.condition==='Limpio y separado'?'selected':''}>Limpio y separado</option><option ${a?.condition==='Mezclado'?'selected':''}>Mezclado</option><option ${a?.condition==='Húmedo o contaminado'?'selected':''}>Húmedo o contaminado</option><option ${a?.condition==='Reutilizable'?'selected':''}>Reutilizable</option></select></div><div><label class="field">Cantidad estimada</label><input class="input" name="quantity" type="number" min="0.1" step="0.1" value="${esc(a?.quantity||'')}" required></div><div><label class="field">Unidad</label><select class="input" name="unit"><option ${a?.unit==='m³'?'selected':''}>m³</option><option ${a?.unit==='kg'?'selected':''}>kg</option><option ${a?.unit==='bolsas'?'selected':''}>bolsas</option><option ${a?.unit==='metros'?'selected':''}>metros</option><option ${a?.unit==='unidades'?'selected':''}>unidades</option></select></div><div class="fullcol"><label class="field">Observaciones para la empresa</label><textarea class="input" name="notes" rows="3" placeholder="Ej: ladrillo limpio, separado y con acceso para camión">${esc(a?.notes||'')}</textarea></div><div class="fullcol"><label class="field">Fotos de respaldo (opcional)</label><input class="input" name="evidence" type="file" accept="image/*" multiple></div><label class="check fullcol"><input type="checkbox" name="hazardous" ${a?.hazardous?'checked':''}> ⚠ Puede contener material peligroso o contaminado</label></div><div class="notice" style="margin-top:14px">La cantidad es una estimación del trabajador. La empresa puede aprobar, ajustar o rechazar el descuento según el valor recuperable y el costo de traslado y clasificación.</div><button class="btn primary full" style="margin-top:18px">Enviar informe a ManosUY</button></form>`) }
async function submitAssessment(e,id){e.preventDefault();const f=new FormData(e.target),old=assessmentFor(id),newEvidence=await filesToPhotos(e.target.evidence.files),data={id:old?.id||'a'+Date.now(),requestId:id,workerId:me().id,material:f.get('material'),condition:f.get('condition'),quantity:f.get('quantity'),unit:f.get('unit'),notes:f.get('notes'),hazardous:!!f.get('hazardous'),evidence:newEvidence.length?newEvidence:(old?.evidence||[]),status:'pending',discount:0,submittedAt:Date.now()};if(old)Object.assign(old,data);else db.assessments.push(data);save();closeModal();app();toast('Informe y fotografías enviados a la empresa')}
function reviewAssessment(id){const a=db.assessments.find(x=>x.id===id),r=db.requests.find(x=>x.id===a.requestId);openModal('Evaluar recuperables · Trabajo #'+a.requestId,`<div class="notice" style="${a.hazardous?'background:#fae8e7;color:var(--red)':''}"><b>${a.hazardous?'⚠ El trabajador marcó posible riesgo':'♻ Material declarado'}</b><br>${esc(a.material)} · ${esc(a.quantity)} ${esc(a.unit)} · ${esc(a.condition)}</div><div class="list-item"><div class="grow"><b>Servicio</b><div class="muted">${esc(r.service)} · ${esc(r.zone)}</div></div></div><p>${esc(a.notes||'Sin observaciones del trabajador.')}</p>${photoGallery(a.evidence,'Evidencia enviada por el trabajador')}<form onsubmit="approveAssessment(event,'${id}')"><div class="formgrid"><div><label class="field">Valor recuperable estimado</label><input class="input" name="recoverableValue" type="number" min="0" required placeholder="Ej: 1400"></div><div><label class="field">Costo de retiro/clasificación</label><input class="input" name="handlingCost" type="number" min="0" required placeholder="Ej: 500"></div><div class="fullcol"><label class="field">Descuento aprobado para el cliente</label><input class="input" name="discount" type="number" min="0" required placeholder="Ej: 900"></div><div class="fullcol"><label class="field">Nota de evaluación</label><textarea class="input" name="adminNote" rows="3" required placeholder="Explicá brevemente cómo se calculó"></textarea></div></div><div class="notice" style="margin-top:14px">Sugerencia: el descuento no debería superar el valor recuperable neto después de traslado, clasificación y disposición segura.</div><div class="actions"><button class="btn primary" type="submit">Aprobar descuento</button><button class="btn danger" type="button" onclick="rejectAssessment('${id}')">Pedir corrección</button></div></form>`) }
function approveAssessment(e,id){e.preventDefault();const f=new FormData(e.target),a=db.assessments.find(x=>x.id===id),value=+f.get('recoverableValue'),cost=+f.get('handlingCost'),discount=+f.get('discount'),net=Math.max(0,value-cost);if(discount>net)return toast(`El descuento no puede superar el valor neto de ${money(net)}`);a.recoverableValue=value;a.handlingCost=cost;a.discount=discount;a.adminNote=f.get('adminNote');a.status='approved';a.reviewedAt=Date.now();save();closeModal();app();toast(`Descuento de ${money(a.discount)} aprobado`)}
function rejectAssessment(id){const a=db.assessments.find(x=>x.id===id);a.status='rejected';a.adminNote='La empresa solicitó revisar la cantidad, el estado o la evidencia presentada.';a.discount=0;save();closeModal();app();toast('Informe devuelto para corrección')}
function updateQuoteTotal(value,discount){const total=document.getElementById('quote-total');if(total)total.textContent=value?money(Math.max(0,+value-discount)):'—'}
function openQuote(id){const r=db.requests.find(x=>x.id===id),a=assessmentFor(id);if(r.materials&&a?.status!=='approved')return toast('La empresa debe aprobar primero el descuento');openModal('Enviar presupuesto final',`<p class="muted">${esc(r.description)}</p>${a?`<div class="notice" style="background:var(--mint);color:var(--green)"><b>Descuento aprobado por ManosUY: ${money(a.discount)}</b><br>${esc(a.material)} · ${esc(a.quantity)} ${esc(a.unit)} · ${esc(a.adminNote||'Evaluación aprobada')}</div>`:''}<form onsubmit="submitQuote(event,'${id}')"><label class="field" style="margin-top:14px">Precio del trabajo antes del descuento (UYU)</label><input class="input" name="amount" type="number" min="1" required placeholder="Ej: 4500" oninput="updateQuoteTotal(this.value,${a?.discount||0})"><label class="field" style="margin-top:13px">Duración estimada</label><input class="input" name="duration" required placeholder="Ej: 2 días"><div class="quote-box"><div><b>Total que verá el cliente</b><div class="meta">Precio menos descuento aprobado</div></div><div class="money" id="quote-total">—</div></div><button class="btn primary full" style="margin-top:18px">Enviar presupuesto final</button></form>`) }
function openRating(id){openModal('Calificar trabajo',`<form onsubmit="submitRating(event,'${id}')"><label class="field">Puntuación</label><select class="input" name="rating"><option value="5">★★★★★ Excelente</option><option value="4">★★★★☆ Muy bueno</option><option value="3">★★★☆☆ Correcto</option><option value="2">★★☆☆☆ Malo</option><option value="1">★☆☆☆☆ Muy malo</option></select><label class="field" style="margin-top:13px">Comentario</label><textarea class="input" name="comment" rows="4" placeholder="Contá cómo fue tu experiencia"></textarea><button class="btn primary full" style="margin-top:18px">Publicar calificación</button></form>`) }
function openChat(id){const msgs=db.messages.filter(m=>m.requestId===id);openModal('Mensajes del trabajo #'+id,`<div style="max-height:280px;overflow:auto">${msgs.map(m=>`<div class="notice" style="margin:8px 0;background:${m.sender===me().id?'var(--mint)':'#f3f4f3'}"><b>${esc(user(m.sender)?.name)}</b><br>${esc(m.text)}</div>`).join('')||'<p class="muted">Todavía no hay mensajes. Coordiná solamente los detalles del trabajo; el pago debe quedar dentro de ManosUY.</p>'}</div><form onsubmit="sendMessage(event,'${id}')"><input class="input" name="text" required placeholder="Escribí un mensaje…"><button class="btn primary full" style="margin-top:9px">Enviar</button></form>`) }
function openClaim(id){openModal('Iniciar reclamo',`<form onsubmit="submitClaim(event,'${id}')"><label class="field">¿Qué ocurrió?</label><select class="input" name="reason"><option>El trabajo no fue terminado</option><option>El resultado no fue el acordado</option><option>Problema con el cobro</option><option>Otro motivo</option></select><label class="field" style="margin-top:13px">Detalles</label><textarea class="input" name="details" rows="4" required></textarea><button class="btn danger full" style="margin-top:18px">Enviar a mediación</button></form>`) }
function openReceipt(id){const r=db.requests.find(x=>x.id===id);openModal('Comprobante #'+id,`<div class="row"><div><div class="eyebrow">Trabajo completado</div><h2>${r.service}</h2></div><span class="badge green">Pagado</span></div><div class="list-item"><div class="grow">Subtotal</div><b>${money(r.quote)}</b></div>${r.discount?`<div class="list-item"><div class="grow">Descuento materiales</div><b>− ${money(r.discount)}</b></div>`:''}<div class="list-item"><div class="grow"><b>Total</b></div><div class="money">${money(r.quote-(r.discount||0))}</div></div><button class="btn full" onclick="toast('Comprobante descargado')">↓ Descargar comprobante</button>`) }
function reviewWorker(id){const w=user(id);openModal('Revisión profesional',`<div class="worker-card" style="grid-template-columns:auto 1fr"><div class="avatar">${initials(w.name)}</div><div><h3>${w.name}</h3><div class="meta">${w.email} · ${w.zone}</div></div></div><h3>Documentación</h3>${(w.documents||[]).map(d=>`<div class="list-item"><div class="list-icon">▤</div><div class="grow"><b>${esc(d.name)}</b><div class="meta">${d.type}</div></div><span class="badge ${d.status==='approved'?'green':'yellow'}">${d.status==='approved'?'Aprobado':'Pendiente'}</span></div>`).join('')||'<p class="notice">El profesional todavía no presentó documentación.</p>'}<div class="actions"><button class="btn primary" onclick="verifyWorker('${id}')">✓ Aprobar perfil</button><button class="btn danger" onclick="rejectWorker('${id}')">Solicitar corrección</button></div>`) }
function openMaterial(){openModal('Registrar material recuperado',`<form onsubmit="saveMaterial(event)"><label class="field">Trabajo de origen</label><select class="input" name="requestId">${db.requests.map(r=>`<option value="${r.id}">#${r.id} · ${r.service}</option>`).join('')}</select><label class="field" style="margin-top:12px">Material</label><input class="input" name="type" required placeholder="Ej: madera recuperable"><div class="formgrid" style="margin-top:12px"><div><label class="field">Volumen</label><input class="input" name="volume" required placeholder="Ej: 2 m³"></div><div><label class="field">Valor estimado</label><input class="input" name="value" type="number" min="0" required></div></div><button class="btn primary full" style="margin-top:18px">Registrar lote</button></form>`) }
function openHelp(){openModal('Cómo funciona ManosUY',`<div class="list-item"><div class="list-icon">1</div><div><b>Contá qué necesitás</b><div class="muted">Elegí servicio, zona y describí el trabajo.</div></div></div><div class="list-item"><div class="list-icon">2</div><div><b>Compará con información real</b><div class="muted">Verificación, experiencia, reputación y presupuesto.</div></div></div><div class="list-item"><div class="list-icon">3</div><div><b>Coordiná y hacé seguimiento</b><div class="muted">Mensajes, estados y comprobantes en un solo lugar.</div></div></div><div class="list-item"><div class="list-icon">4</div><div><b>Calificá el resultado</b><div class="muted">Tu opinión mejora la seguridad de toda la comunidad.</div></div></div>`) }
function openModal(title,body){document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><header class="modal-head"><h2>${title}</h2><button class="close" onclick="closeModal()" aria-label="Cerrar">×</button></header><div class="modal-body">${body}</div></div></div>`}
function closeModal(){document.getElementById('modal-root').innerHTML=''}function empty(t,s){return `<div class="empty"><div class="empty-icon">✦</div><b>${t}</b><div>${s}</div></div>`}
function login(e){e.preventDefault();const f=new FormData(e.target),u=db.users.find(x=>x.email.toLowerCase()===String(f.get('email')).toLowerCase()&&x.password===f.get('password'));if(!u)return toast('Correo o contraseña incorrectos');if(!u.active)return toast('Esta cuenta está suspendida');session={userId:u.id};page='home';save();app()}
function register(e){e.preventDefault();const f=new FormData(e.target),email=String(f.get('email')).trim();if(db.users.some(u=>u.email.toLowerCase()===email.toLowerCase()))return toast('Ese correo ya está registrado');const role=f.get('role'),services=f.getAll('services');if(role==='worker'&&!services.length)return toast('Elegí al menos un servicio');const u={id:'u'+Date.now(),role,name:String(f.get('name')).trim(),email,phone:f.get('phone'),zone:f.get('zone'),password:f.get('password'),active:true};if(role==='worker')Object.assign(u,{services,bio:'Nuevo profesional en ManosUY.',rating:0,jobs:0,verified:false,available:true,level:'Inicial',experience:0,documents:[]});db.users.push(u);session={userId:u.id};save();page='home';app();toast('¡Cuenta creada! Completá tu perfil.')}
async function createRequest(e,workerId){e.preventDefault();const f=new FormData(e.target),photos=await filesToPhotos(e.target.photos.files),r={id:String(db.nextRequest++),clientId:me().id,workerId:workerId||null,service:f.get('service'),zone:f.get('zone'),address:f.get('address'),description:f.get('description'),urgent:!!f.get('urgent'),materials:!!f.get('materials'),photos,status:workerId?'pending':'open',created:Date.now(),quote:0,discount:0};db.requests.push(r);save();closeModal();page='requests';app();toast(`Solicitud publicada con ${photos.length} foto(s)`) }
function submitQuote(e,id){e.preventDefault();const f=new FormData(e.target),r=db.requests.find(x=>x.id===id),a=assessmentFor(id);r.quote=+f.get('amount');r.duration=f.get('duration');r.discount=a?.discount||0;r.status='quoted';save();closeModal();app();toast('Presupuesto final enviado al cliente')}
function submitRating(e,id){e.preventDefault();const f=new FormData(e.target),r=db.requests.find(x=>x.id===id),w=user(r.workerId);db.ratings.push({requestId:id,clientId:me().id,workerId:w.id,rating:+f.get('rating'),comment:f.get('comment')});const all=db.ratings.filter(x=>x.workerId===w.id);w.rating=Math.round(all.reduce((a,x)=>a+x.rating,0)/all.length*10)/10;save();closeModal();app();toast('Gracias por compartir tu experiencia')}
function sendMessage(e,id){e.preventDefault();const f=new FormData(e.target);db.messages.push({id:'msg'+Date.now(),requestId:id,sender:me().id,text:f.get('text'),created:Date.now()});save();openChat(id)}
function submitClaim(e,id){e.preventDefault();const f=new FormData(e.target);db.claims.push({id:String(Date.now()).slice(-5),requestId:id,clientId:me().id,reason:f.get('reason'),details:f.get('details'),status:'open'});save();closeModal();toast('Reclamo enviado a mediación')}
function saveProfile(e){e.preventDefault();const f=new FormData(e.target),u=me();u.name=f.get('name');u.phone=f.get('phone');u.zone=f.get('zone');if(u.role==='worker'){u.bio=f.get('bio');u.experience=+f.get('experience');u.available=f.get('available')==='true';u.services=f.getAll('services')}save();app();toast('Perfil actualizado')}
function addDocument(e){e.preventDefault();const f=new FormData(e.target),file=e.target.document.files[0];me().documents.push({name:file.name,type:f.get('type'),status:'pending'});me().verified=false;save();app();toast('Documento enviado a revisión')}
function saveMaterial(e){e.preventDefault();const f=new FormData(e.target);db.materials.push({id:'m'+Date.now(),requestId:f.get('requestId'),type:f.get('type'),volume:f.get('volume'),value:+f.get('value'),status:'Clasificado'});save();closeModal();app();toast('Material registrado')}
function changeStatus(id,status,msg){const r=db.requests.find(x=>x.id===id),was=r.status;r.status=status;if(status==='completed'&&was!=='completed'&&r.workerId){const w=user(r.workerId);w.jobs++;w.level=w.jobs>=300&&w.rating>=4.7?'Premium':w.jobs>=101?'Experto':w.jobs>=21?'Profesional':'Inicial';if(r.materials&&!db.materials.some(m=>m.requestId===id))db.materials.push({id:'m'+Date.now(),requestId:id,type:'Material por clasificar',volume:'Pendiente',status:'Recibido',value:0})}save();app();toast(msg)}
function verifyWorker(id){const w=user(id);w.verified=true;(w.documents||[]).forEach(d=>d.status='approved');save();closeModal();app();toast('Profesional verificado')}function rejectWorker(id){user(id).verified=false;save();closeModal();toast('Se solicitó corregir la documentación')}
function toggleUser(id){user(id).active=!user(id).active;save();app();toast('Estado de cuenta actualizado')}function resolveClaim(id){const c=db.claims.find(x=>x.id===id);c.status='resolved';save();app();toast('Reclamo marcado como resuelto')}
function toggleAvailability(){me().available=!me().available;save();app();toast(me().available?'Ahora figurás disponible':'Disponibilidad pausada')}
function setAuth(m){authMode=m;app()}function toggleRegisterServices(v){document.getElementById('reg-services').style.display=v==='worker'?'block':'none'}function go(p){page=p;app();window.scrollTo(0,0)}function logout(){session=null;page='home';save();app()}function homeSearch(e){e.preventDefault();filters.q=new FormData(e.target).get('q');go('find')}function pickService(s){filters.q=s;go('find')}function setFilter(k,v){filters[k]=v;document.querySelector('.main').innerHTML=findView()}function openGeneralRequest(){openRequest()}function netEarnings(id){return Math.round(db.requests.filter(r=>r.workerId===id&&r.status==='completed').reduce((a,r)=>a+(r.quote||0),0)*.85)}
function roleLabel(r){return r==='client'?'Cliente':r==='worker'?'Profesional':'Administrador'}function statusLabel(s){return ({open:'Abierta',pending:'Esperando presupuesto',quoted:'Presupuesto recibido',in_progress:'En curso',completed:'Completado',rejected:'Rechazado'})[s]||s}function statusClass(s){return ({open:'blue',pending:'yellow',quoted:'blue',in_progress:'blue',completed:'green',rejected:'red'})[s]||'yellow'}function levelIcon(l){return ({Premium:'💎',Experto:'🥇',Profesional:'🥈',Inicial:'🥉'})[l]||'🥉'}
function toast(msg){const root=document.getElementById('toast-root'),t=document.createElement('div');t.className='toast';t.textContent=msg;root.appendChild(t);setTimeout(()=>t.remove(),2600)}
Object.assign(window,{setAuth,toggleRegisterServices,login,register,go,logout,homeSearch,pickService,setFilter,openGeneralRequest,openWorker,openRequest,createRequest,closeModal,openPhoto,openAdminRequest,openQuote,submitQuote,changeStatus,openRating,submitRating,openChat,sendMessage,openClaim,submitClaim,openReceipt,saveProfile,addDocument,toggleAvailability,openHelp,reviewWorker,verifyWorker,rejectWorker,toggleUser,resolveClaim,openMaterial,saveMaterial,openAssessment,submitAssessment,reviewAssessment,approveAssessment,rejectAssessment,updateQuoteTotal,toast});app();
